-- PT122-S2-Q5. Approved 2026-10-01.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT122-S2-Q5$batch02$ AND q.stimulus=$batch02$Letter to the editor: Middle-class families in wealthy nations are often criticized for the ecological damage resulting from their lifestyles. This criticism should not be taken too seriously, however, since its source is often a movie star or celebrity whose own lifestyle would, if widely adopted, destroy the environment and deplete our resources in a short time.$batch02$ AND q.prompt=$batch02$The reasoning in the letter to the editor is vulnerable to criticism in that it$batch02$ AND q.correct_choice=$batch02$A$batch02$) THEN RAISE EXCEPTION 'Question changed: PT122-S2-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT122-S2-Q5$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT122-S2-Q5$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The criticism of middle-class families' ecological damage should not be taken too seriously.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$The critics are often celebrities whose own lifestyles are far more damaging.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Suppose the celebrities really are hypocrites. Does that make middle-class lifestyles any less damaging? No. A smoker who tells you smoking is bad for you is still right. The letter answers the criticism by pointing at the critics, and never says a word about whether the damage is real.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Expect the ad hominem answer: rejecting a claim because of something about the people making it.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT122-S2-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The letter attacks the critics' lifestyles, not the substance of their criticism. Whether the critics live up to their own standard does not affect whether middle-class lifestyles cause ecological damage. This is the "you do it too" version of ad hominem.$batch02$), ($batch02$B$batch02$, $batch02$This tempts because the letter does point to inconsistency between the celebrities' words and their lives. But the letter never draws a conclusion about how *sincerely* they hold their views. It uses the inconsistency to dismiss the criticism, which is (A).$batch02$), ($batch02$C$batch02$, $batch02$The letter never examines the critics' grounds at all, adequate or not. It dismisses the criticism by looking at who makes it.$batch02$), ($batch02$D$batch02$, $batch02$No evidence in the letter backfires on its conclusion. The celebrities' lifestyles are a different topic from middle-class families' damage.$batch02$), ($batch02$E$batch02$, $batch02$The letter does not generalize from a few people to everyone. It describes one group of critics and then dismisses their argument.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT122-S2-Q5$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
